	public static SharpieArt? Resolve(string? style, string? genre, string? subgenre, string? overrideId, GuideImagery imagery, SharpieArtMoment moment = SharpieArtMoment.Lesson, string? topic = null)
		=> ResolveFrom(Approved, style, genre, subgenre, overrideId, imagery, moment, topic);

	internal static SharpieArt? ResolveFrom(IReadOnlyList<SharpieArt> approved, string? style, string? genre, string? subgenre, string? overrideId, GuideImagery imagery, SharpieArtMoment moment = SharpieArtMoment.Lesson, string? topic = null)
	{
		if (imagery == GuideImagery.None) return null;
		var family = style is not null && Styles.Contains(style) ? style : "minimalist";
		var requestedTopic = moment switch
		{
			SharpieArtMoment.Welcome => "shared-welcome",
			SharpieArtMoment.Completion => "shared-completion",
			_ => topic
		};
		var neutralId = moment switch
		{
			SharpieArtMoment.Welcome => "sharpie-primary-neutral",
			SharpieArtMoment.Completion => "sharpie-smile-neutral",
			_ => "sharpie-minimal-neutral"
		};
		SharpieArt? Find(string? theme, string? targetTopic) => approved.FirstOrDefault(art => art.Style == family
			&& art.Topic == targetTopic && string.Equals(art.Theme, theme, StringComparison.OrdinalIgnoreCase));
		return approved.FirstOrDefault(art => art.Id == overrideId && art.Style == family && (art.Topic is null || art.Topic == requestedTopic))
			?? (requestedTopic is null ? null : Find(subgenre, requestedTopic) ?? Find(genre, requestedTopic))
			?? Find(subgenre, null)
			?? Find(genre, null)
			?? approved.FirstOrDefault(art => art.Id == neutralId && art.Topic is null);
	}
}
